// ===============================================
// CONFIG
// ===============================================
const MAX_DISTANCE = 20;  // distancia máxima entre IDs Modbus
let tabla = msg.payload;

// ===============================================
// 1. VALIDAR Y LIMPIAR
// ===============================================
let registros = tabla.filter(r =>
    r &&
    r.Ambiente &&
    r.Sensor &&
    typeof r.IDModbus === "number"
);

if (registros.length === 0) {
    msg.payload = { ok: false, error: "No hay filas válidas" };
    return msg;
}

// ===============================================
// 2. AGRUPAR POR AMBIENTE
// ===============================================
let gruposAmbiente = {};

registros.forEach(r => {
    if (!gruposAmbiente[r.Ambiente]) gruposAmbiente[r.Ambiente] = [];
    gruposAmbiente[r.Ambiente].push(r);
});

// ===============================================
// 3. AGRUPAR POR IDModbus (USANDO DIFERENCIA ENTRE REGISTROS SEGUIDOS)
// ===============================================
let resultado = {};

Object.keys(gruposAmbiente).forEach(amb => {

    let lista = gruposAmbiente[amb];

    // Ordenar por IDModbus ascendente
    lista.sort((a, b) => a.IDModbus - b.IDModbus);

    let subgrupos = [];
    let actual = [lista[0]];

    for (let i = 1; i < lista.length; i++) {
        const prev = lista[i - 1].IDModbus;
        const curr = lista[i].IDModbus;

        // Si la distancia entre registros consecutivos supera el límite → nuevo grupo
        if ((curr - prev) > MAX_DISTANCE) {
            subgrupos.push(actual);
            actual = [lista[i]];
        } else {
            actual.push(lista[i]);
        }
    }

    // guardar último grupo
    if (actual.length > 0) subgrupos.push(actual);

    resultado[amb] = subgrupos;
});

// ===============================================
// 4. SALIDA
// ===============================================
msg.payload = {
    ok: true,
    ambientes: Object.keys(resultado).length,
    grupos: resultado
};

global.set("modbus32.compact", resultado);

return msg;

const compact = global.get("modbus32.compact");
