for (let idxAmb = 0; idxAmb < ambientes.length; idxAmb++) {
    const ambiente = ambientes[idxAmb];
    const subgrupos = compact[ambiente];

    if (!Array.isArray(subgrupos) || subgrupos.length === 0) {
        node.warn("⚠️ Ambiente vacío: " + ambiente);
        continue;
    }

    for (let idxGrupo = 0; idxGrupo < subgrupos.length; idxGrupo++) {
        const sensores = subgrupos[idxGrupo];

        if (!Array.isArray(sensores) || sensores.length === 0) {
            node.warn(`⚠️ Subgrupo vacío → Ambiente: ${ambiente}, Grupo: ${idxGrupo}`);
            continue;
        }

        node.send({
            payload: sensores,
            info: {
                ambiente,
                grupo: idxGrupo,
                totalGrupos: subgrupos.length,
                sensorCount: sensores.length,
                ambienteIndex: idxAmb,
                totalAmbientes: ambientes.length
            }
        });
    }
}

